  const RCSS = "\n\n:root{--bg:#ffffff;--ink:#15192B;--mut:#6A6F85;--body:#3B3F57;--lime:#D3F36B;--lav:#7B5CF0;--lila:#B9A6FF;--peri:#C9D2FF;--pink:#FF8FC0;--pinkL:#FFC7E2;--soft:#F7F5FC;--dot:#ECE6FA}\n:root[data-theme=\"dark\"]{--bg:#10131F}\n*,*::before,*::after{box-sizing:border-box}\nbody{margin:0;width:816px;background:#fff;font-family:\"Plus Jakarta Sans\",system-ui,sans-serif;color:var(--ink);-webkit-font-smoothing:antialiased}\n.page{background:#fff;width:816px;margin:0 0 40px;position:relative;display:flex;flex-direction:column;min-height:1056px}\n.br{font-family:\"Bricolage Grotesque\",sans-serif}\n.hd{background:var(--ink);color:#fff;padding:28px 56px 26px;position:relative;overflow:hidden;display:flex;justify-content:space-between;align-items:center;gap:20px}\n.hd .ring{position:absolute;right:-60px;top:-110px;width:260px;height:260px;border-radius:50%;border:36px solid rgba(185,166,255,.16)}\n.mova{font-family:\"Bricolage Grotesque\",sans-serif;font-weight:800;font-size:32px;letter-spacing:.08em;line-height:1}\n.cp{font-size:9.5px;font-weight:700;letter-spacing:.16em;color:#AEB3CC;margin-top:7px}\n.tag{display:inline-block;background:var(--lime);color:var(--ink);font-size:9.5px;font-weight:800;letter-spacing:.14em;border-radius:999px;padding:7px 16px;margin-top:16px}\n.meta{position:relative;display:grid;gap:9px;align-content:start;text-align:right;font-size:12.5px}\n.meta span{color:#AEB3CC;font-weight:600;margin-right:10px}.meta b{font-weight:800}\n.mini{background:var(--ink);color:#fff;padding:20px 56px;display:flex;justify-content:space-between;align-items:center}\n.mini .mova{font-size:22px}\n.mini .nm{display:flex;align-items:center;gap:12px;font-weight:800;font-size:14px}\n.mini .gp{background:var(--lime);color:var(--ink);border-radius:999px;padding:5px 12px;font-size:12px}\n.ct{padding:34px 56px 20px;flex:1}\n.kick{font-size:11px;font-weight:800;letter-spacing:.18em;color:var(--lav)}\n.name{font-family:\"Bricolage Grotesque\",sans-serif;font-weight:800;font-size:40px;letter-spacing:-.02em;line-height:1.05;margin:12px 0 10px}\n.line{width:54px;height:6px;border-radius:9px;background:var(--lime)}\n.card{background:var(--ink);color:#fff;border-radius:22px;padding:22px 26px;margin:22px 0 6px;display:grid;grid-template-columns:1.1fr 1fr;gap:22px;position:relative;overflow:hidden}\n.card .arc{position:absolute;left:-40px;bottom:-110px;width:200px;height:200px;border-radius:50%;border:30px solid rgba(211,243,107,.10)}\n.card small{display:block;font-size:9.5px;font-weight:800;letter-spacing:.16em;color:#AEB3CC}\n.card .big{font-family:\"Bricolage Grotesque\",sans-serif;font-weight:800;font-size:34px;color:var(--lime);line-height:1;margin:10px 0 6px}\n.card .sub{font-family:\"Bricolage Grotesque\",sans-serif;font-weight:700;font-size:17px}\n.tiles{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;align-content:center;position:relative}\n.tiles span{aspect-ratio:1.25;border-radius:12px;display:grid;place-items:center;font-family:\"Bricolage Grotesque\",sans-serif;font-weight:800;font-size:15px;color:var(--ink)}\n.cnt{display:flex;gap:14px;flex-wrap:wrap;margin-top:12px;font-size:11.5px;font-weight:700;color:#C9CCE0}\n.cnt i{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:6px;vertical-align:-1px}\n.sh{display:flex;align-items:center;gap:12px;margin:30px 0 12px}\n.sh .v{width:34px;height:34px;border-radius:11px;display:grid;place-items:center;flex:none;box-shadow:0 3px 0 var(--ink);border:2px solid var(--ink)}\n.sh .v svg{width:17px;height:17px}\n.sh h2{font-family:\"Bricolage Grotesque\",sans-serif;font-size:21px;margin:0;letter-spacing:-.01em}\n.p{font-size:13.5px;line-height:1.7;color:var(--body);margin:0}\n.row{display:grid;grid-template-columns:24px 1fr auto;align-items:center;gap:12px;background:var(--soft);border-radius:14px;padding:12px 16px;margin-bottom:7px}\n.bul{width:16px;height:16px;border-radius:50%;border:2px solid var(--ink)}\n.row b{font-size:14px;font-weight:700}\n.row small{display:block;font-size:11.5px;color:var(--mut);font-weight:500;margin-top:2px;line-height:1.4}\n.pill{font-size:9.5px;font-weight:800;letter-spacing:.12em;padding:6px 11px;border-radius:999px;color:var(--ink);white-space:nowrap}\n.row.rz{background:#fff;border:2px dashed #DCD5F2}\n.row.pr{background:#fff;border:1px solid var(--dot)}\n.legend{display:flex;gap:16px;flex-wrap:wrap;margin-top:10px;font-size:11.5px;font-weight:700;color:var(--mut)}\n.legend i{display:inline-block;width:11px;height:11px;border-radius:50%;border:1.5px solid var(--ink);margin-right:6px;vertical-align:-1px}\n.two{display:grid;grid-template-columns:1fr 1fr;gap:14px}\n.bx{border-radius:18px;padding:18px 20px}\n.bx h3{font-family:\"Bricolage Grotesque\",sans-serif;font-size:16px;margin:0 0 10px;display:flex;align-items:center;gap:8px}\n.bx ul{list-style:none;margin:0;padding:0}.bx li{display:flex;gap:10px;font-size:13px;line-height:1.55;color:var(--body);margin-bottom:8px}\n.ck{flex:none;width:18px;height:18px;border-radius:50%;border:1.5px solid var(--ink);display:grid;place-items:center;margin-top:1px}\n.ck svg{width:10px;height:10px}\n.opp{display:grid;gap:10px}\n.oc{border-radius:18px;padding:16px 18px 16px 18px;display:grid;grid-template-columns:40px 1fr;gap:14px;position:relative;overflow:hidden}\n.oc .n{width:40px;height:40px;border-radius:12px;background:#fff;border:2px solid var(--ink);display:grid;place-items:center;font-family:\"Bricolage Grotesque\",sans-serif;font-weight:800;font-size:17px;box-shadow:0 3px 0 var(--ink)}\n.oc .e{font-size:10px;font-weight:800;letter-spacing:.12em;color:var(--ink);opacity:.6}\n.oc b{display:block;font-family:\"Bricolage Grotesque\",sans-serif;font-size:16px;margin:3px 0 6px}\n.oc p{margin:0;font-size:13px;line-height:1.6;color:var(--body)}\n.oc .how{margin-top:8px;font-size:12.5px;font-weight:600;color:var(--ink);display:flex;gap:8px}\n.oc .how i{font-style:normal;font-weight:800;white-space:nowrap}\n.route{display:grid;gap:8px}\n.rt{display:grid;grid-template-columns:34px 1fr;gap:14px;align-items:center;background:var(--soft);border-radius:14px;padding:11px 14px}\n.rt span{width:34px;height:34px;border-radius:50%;background:var(--ink);color:var(--lime);display:grid;place-items:center;font-family:\"Bricolage Grotesque\",sans-serif;font-weight:800;font-size:15px}\n.rt b{display:block;font-size:13.5px}.rt small{font-size:12px;color:var(--mut)}\n.tips{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.tp{border:1.5px solid var(--dot);border-radius:16px;padding:14px 16px}\n.tp b{display:flex;align-items:center;gap:8px;font-size:13.5px;margin-bottom:5px}\n.tp b i{width:10px;height:10px;border-radius:50%;flex:none}\n.tp p{margin:0;font-size:12.5px;line-height:1.55;color:var(--body)}\n.tch{background:#F1FBD2;border-radius:20px;padding:20px 22px;font-size:13.5px;line-height:1.75;color:var(--body)}\n.sig{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-top:26px}\n.sig .ln{width:220px;border-top:1.5px solid var(--ink);padding-top:8px}\n.sig b{display:block;font-size:13px}.sig small{font-size:11.5px;color:var(--mut);font-weight:600}\n.nxt{background:var(--ink);color:#fff;border-radius:16px;padding:14px 18px;font-size:12.5px;line-height:1.55;max-width:330px}\n.nxt b{color:var(--lime)}\n.ft{margin:0 56px;border-top:1px solid var(--dot);padding:14px 0 22px;display:flex;justify-content:space-between;gap:10px;font-size:10px;color:var(--mut);font-weight:600}\n.ft b{color:var(--ink)}\n.dots{position:absolute;right:28px;top:1px;display:grid;grid-template-columns:repeat(8,6px);gap:8px;opacity:.9}\n.logo{height:54px;width:auto;display:block;position:relative;flex:none}\n.hl{position:relative}\n.meta2{display:grid;grid-template-columns:auto 1fr;column-gap:12px;row-gap:3px;margin-top:14px;font-size:12px;line-height:1.35}\n.meta2 span{color:#AEB3CC;font-weight:600}.meta2 b{font-weight:800}\n.chart{display:flex;align-items:flex-end;justify-content:center;gap:16px;height:150px;position:relative;padding-top:8px}\n.chart .c{display:flex;flex-direction:column;align-items:center;gap:7px;width:64px}\n.chart .c b{font-family:\"Bricolage Grotesque\",sans-serif;font-size:22px;line-height:1}\n.chart .c i{display:block;width:100%;border-radius:12px 12px 6px 6px}\n.chart .c small{font-size:9px;font-weight:800;letter-spacing:.1em;color:#C9CCE0;text-align:center;line-height:1.3}\n.nxt2{background:var(--ink);color:#fff;border-radius:18px;padding:16px 22px;font-size:13px;line-height:1.6;margin-top:22px;display:flex;align-items:center;gap:16px}\n.nxt2 .ic{flex:none;width:40px;height:40px;border-radius:12px;background:var(--lime);display:grid;place-items:center}\n.nxt2 b{color:var(--lime)}\n.sig2{margin:26px auto 0;width:260px;text-align:center}\n.sig2 img{height:64px;display:block;margin:0 auto -8px}\n.sig2 .ln{border-top:1.5px solid var(--ink);padding-top:8px}\n.sig2 b{display:block;font-size:13px}.sig2 small{font-size:11.5px;color:var(--mut);font-weight:600}\n.oc .how{display:block}\n.oc .how i{display:block;font-size:10px;letter-spacing:.12em;font-weight:800;margin-bottom:3px;opacity:.75}\n.oc .how span{display:block;font-weight:600;line-height:1.55}\n";

